create sequence pipeline.integration_issues_id_seq;
create sequence pipeline.ops_ai_diagnosis_requests_id_seq;
-- Guards: Provider Description existing AI-diagnostics governed tables, authoritative schema only.
create table pipeline.integration_issues (id int8 default nextval('pipeline.integration_issues_id_seq'::regclass) not null,issue_ref text,fingerprint text not null,title text not null,layer text not null,subsystem text,provider_ids _uuid default '{}'::uuid[] not null,course_ids _uuid default '{}'::uuid[] not null,country_codes _text default '{}'::text[] not null,entities_truncated bool default false not null,detected_at timestamptz default now() not null,failure text not null,expected text not null,detection_source text not null,validation_layer text default 'manual'::text not null,evidence jsonb default '{}'::jsonb not null,evidence_refs _text default '{}'::text[] not null,root_cause_class text default 'unclassified'::text not null,severity text not null,impact text,workstream text not null,blocked_by _int8 default '{}'::bigint[] not null,depends_on _text default '{}'::text[] not null,fix_commit text,fix_migration text,deployed_version text,verification_outcome text,verification_evidence jsonb,verified_at timestamptz,verified_by text,retry_count int4 default 0 not null,last_observed_at timestamptz default now() not null,condition_cleared_at timestamptz,status text default 'detected'::text not null,assignee text,regression_count int4 default 0 not null,reopened_at timestamptz,closed_at timestamptz,aer_root_cause_ref text,alert_check_key text,created_at timestamptz default now() not null,updated_at timestamptz default now() not null,correlation_key text,diagnosis jsonb,remedy_code text,remedy_attempts int4 default 0 not null,next_action_at timestamptz,ops_state text,superseded_by int8,supersedes _int8 default '{}'::bigint[] not null,blocker jsonb,ops_plan jsonb,remediation_owner text,remediation_status text,remediation_checkpoint_at timestamptz,remediation_evidence jsonb,severity_decided_at timestamptz,severity_decided_by text,severity_decision jsonb);
create table pipeline.ops_root_causes (code text not null,class text not null,title text not null,description text,detect jsonb default '{}'::jsonb not null,created_at timestamptz default now() not null);
create table pipeline.ops_ai_diagnosis_requests (id int8 default nextval('pipeline.ops_ai_diagnosis_requests_id_seq'::regclass) not null,issue_id int8 not null,requested_at timestamptz default now() not null,state text default 'queued'::text not null,leased_until timestamptz,context jsonb not null,answer jsonb,model text,cost_usd numeric,answered_at timestamptz,note text);
alter table pipeline.integration_issues add constraint integration_issues_fingerprint_check CHECK (length(btrim(fingerprint)) > 0);
alter table pipeline.integration_issues add constraint integration_issues_fingerprint_key UNIQUE (fingerprint);
alter table pipeline.integration_issues add constraint integration_issues_ops_state_check CHECK (ops_state IS NULL OR (ops_state = ANY (ARRAY['diagnosed'::text, 'remedying'::text, 'verifying'::text, 'verified'::text, 'superseded'::text, 'needs_release'::text, 'needs_decision'::text])));
alter table pipeline.integration_issues add constraint integration_issues_pkey PRIMARY KEY (id);
alter table pipeline.integration_issues add constraint integration_issues_remediation_status_check CHECK (remediation_status IS NULL OR (remediation_status = ANY (ARRAY['engineering_open'::text, 'fix_released'::text, 'awaiting_first_run'::text, 'verified'::text, 'returned'::text])));
alter table pipeline.integration_issues add constraint integration_issues_root_cause_class_check CHECK (root_cause_class = ANY (ARRAY['unclassified'::text, 'code_defect'::text, 'data_drift'::text, 'job_config'::text, 'lifecycle_leak'::text, 'queue_or_lease'::text, 'missing_dependency'::text, 'governance_gap'::text, 'external'::text, 'budget'::text, 'human_decision'::text, 'deployment_drift'::text]));
alter table pipeline.integration_issues add constraint integration_issues_severity_check CHECK (severity = ANY (ARRAY['P0'::text, 'P1'::text, 'P2'::text]));
alter table pipeline.integration_issues add constraint integration_issues_status_check CHECK (status = ANY (ARRAY['detected'::text, 'triaged'::text, 'assigned'::text, 'in_progress'::text, 'code_ready'::text, 'integration_testing'::text, 'deployed'::text, 'production_verification'::text, 'closed'::text, 'reopened'::text]));
alter table pipeline.integration_issues add constraint integration_issues_superseded_by_fkey FOREIGN KEY (superseded_by) REFERENCES pipeline.integration_issues(id);
alter table pipeline.integration_issues add constraint integration_issues_validation_layer_check CHECK (validation_layer = ANY (ARRAY['V1'::text, 'V2'::text, 'V3'::text, 'V4'::text, 'manual'::text]));
alter table pipeline.integration_issues add constraint integration_issues_verification_outcome_check CHECK (verification_outcome = ANY (ARRAY['passed'::text, 'failed'::text, 'regressed'::text]));
alter table pipeline.integration_issues add constraint integration_issues_workstream_check CHECK (workstream = ANY (ARRAY['A1'::text, 'A2'::text, 'A3'::text, 'A4'::text, 'A5'::text, 'A6'::text, 'A7'::text, 'A8'::text, 'A9'::text, 'A10'::text]));
alter table pipeline.ops_root_causes add constraint ops_root_causes_class_check CHECK (class = ANY (ARRAY['transient'::text, 'data'::text, 'rule'::text, 'policy'::text, 'dependency'::text, 'capacity'::text]));
alter table pipeline.ops_root_causes add constraint ops_root_causes_code_check CHECK (code ~ '^[a-z][a-z0-9_]*$'::text);
alter table pipeline.ops_root_causes add constraint ops_root_causes_pkey PRIMARY KEY (code);
alter table pipeline.ops_ai_diagnosis_requests add constraint ops_ai_diagnosis_requests_issue_id_fkey FOREIGN KEY (issue_id) REFERENCES pipeline.integration_issues(id);
alter table pipeline.ops_ai_diagnosis_requests add constraint ops_ai_diagnosis_requests_pkey PRIMARY KEY (id);
alter table pipeline.ops_ai_diagnosis_requests add constraint ops_ai_diagnosis_requests_state_check CHECK (state = ANY (ARRAY['queued'::text, 'leased'::text, 'answered'::text, 'refused'::text]));
CREATE UNIQUE INDEX IF NOT EXISTS integration_issues_pkey ON pipeline.integration_issues USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS integration_issues_fingerprint_key ON pipeline.integration_issues USING btree (fingerprint);
CREATE UNIQUE INDEX IF NOT EXISTS integration_issues_aer_ref_uq ON pipeline.integration_issues USING btree (aer_root_cause_ref) WHERE (aer_root_cause_ref IS NOT NULL);
CREATE INDEX IF NOT EXISTS integration_issues_open_idx ON pipeline.integration_issues USING btree (status, severity) WHERE (status <> 'closed'::text);
CREATE INDEX IF NOT EXISTS integration_issues_observed_idx ON pipeline.integration_issues USING btree (last_observed_at DESC);
CREATE INDEX IF NOT EXISTS integration_issues_next_action_idx ON pipeline.integration_issues USING btree (next_action_at) WHERE (status <> 'closed'::text);
CREATE INDEX IF NOT EXISTS integration_issues_correlation_idx ON pipeline.integration_issues USING btree (correlation_key) WHERE (status <> 'closed'::text);
CREATE UNIQUE INDEX IF NOT EXISTS ops_ai_diagnosis_requests_pkey ON pipeline.ops_ai_diagnosis_requests USING btree (id);
CREATE INDEX IF NOT EXISTS ops_ai_diagnosis_requests_open_idx ON pipeline.ops_ai_diagnosis_requests USING btree (state, requested_at) WHERE (state = ANY (ARRAY['queued'::text, 'leased'::text]));
CREATE UNIQUE INDEX IF NOT EXISTS ops_root_causes_pkey ON pipeline.ops_root_causes USING btree (code);
